import React, { forwardRef, useState } from 'react';
import { isUndefined } from 'lodash';
import type { Types } from '@fiverr-private/theme';
import BaseButton from '../BaseButton';
import type { ToggleButtonProps } from './types';

const getColorStylingProps = (isSelected: ToggleButtonProps['isSelected']): Types.BoxType => ({
  color: isSelected ? 'bodyPrimary' : 'bodySecondary',
  backgroundColor: isSelected ? 'grey_500' : { default: 'transparent', hover: 'grey_300', active: 'grey_500' },
});

const ToggleButton = forwardRef<HTMLButtonElement, ToggleButtonProps>(
  (
    {
      children,
      isSelected: isSelectedProp,
      initialSelected,
      onSelectedChanged,
      onClick,
      disabled,
      dataTrackTag = 'toggle_button',
      ...rest
    },
    ref
  ) => {
    const [isSelectedInner, setIsSelectedInner] = useState(initialSelected);
    const isSelected = isUndefined(isSelectedProp) ? isSelectedInner : isSelectedProp;
    const { color, backgroundColor } = getColorStylingProps(isSelected);

    const onButtonClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      setIsSelectedInner(!isSelected);
      onSelectedChanged?.(!isSelected);
      onClick?.(e);
    };

    return (
      <BaseButton
        ref={ref}
        type="button"
        intent="secondary"
        variant="ghost"
        width={28}
        height={28}
        disabled={disabled}
        color={disabled ? 'grey_800' : color}
        backgroundColor={disabled ? undefined : backgroundColor}
        onClick={onButtonClick}
        borderRadius="md"
        dataTrackTag={dataTrackTag}
        {...rest}
      >
        {children}
      </BaseButton>
    );
  }
);

ToggleButton.displayName = 'ToggleButton';

export default ToggleButton;
